const body = $input.first().json.body || {};
const missing = ['company_name','raw_data'].filter(f => !body[f] || String(body[f]).trim() === '');
if (missing.length > 0) {
  return [{ json: { _valid: false, _error: 'Missing required fields: ' + missing.join(', ') } }];
}
return [{ json: { ...$input.first().json, _valid: true } }];

